package com.blackscreenfocus;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;

@ConfigGroup(BlackScreenFocusConfig.GROUP)
public interface BlackScreenFocusConfig extends Config
{
	String GROUP = "blackscreenfocus";

	enum Horizontal
	{
		LEFT(0), CENTER(0.5), RIGHT(1);

		final double fraction;

		Horizontal(double fraction)
		{
			this.fraction = fraction;
		}
	}

	enum Vertical
	{
		TOP(0), CENTER(0.5), BOTTOM(1);

		final double fraction;

		Vertical(double fraction)
		{
			this.fraction = fraction;
		}
	}

	@Range(min = ViewportMath.MIN_PERCENT, max = ViewportMath.MAX_PERCENT)
	@ConfigItem(keyName = "widthPercent", name = "Width %", description = "Game width as a percent of the client window.", position = 1)
	default int widthPercent()
	{
		return 60;
	}

	@ConfigItem(keyName = "linkHeight", name = "Height follows width", description = "When ticked, Height % below is ignored and the width % is used for the height too.", position = 2)
	default boolean linkHeight()
	{
		return false;
	}

	@Range(min = ViewportMath.MIN_PERCENT, max = ViewportMath.MAX_PERCENT)
	@ConfigItem(keyName = "heightPercent", name = "Height %", description = "Game height as a percent of the client window. Only used when 'Height follows width' is off.", position = 3)
	default int heightPercent()
	{
		return 60;
	}

	@ConfigItem(keyName = "horizontal", name = "Horizontal position", description = "Where the game sits left to right.", position = 4)
	default Horizontal horizontal()
	{
		return Horizontal.CENTER;
	}

	@ConfigItem(keyName = "vertical", name = "Vertical position", description = "Where the game sits top to bottom.", position = 5)
	default Vertical vertical()
	{
		return Vertical.CENTER;
	}

	@ConfigItem(keyName = "background", name = "Empty space colour", description = "Colour of the area around the game.", position = 6)
	default Color background()
	{
		return Color.BLACK;
	}

	@ConfigItem(keyName = "toggleHotkey", name = "Toggle hotkey", description = "Switch between the small and full-size game. Works while the plugin is enabled.", position = 7)
	default Keybind toggleHotkey()
	{
		return Keybind.NOT_SET;
	}
}

package com.blackscreenfocus;

import com.google.inject.Provides;
import java.awt.Canvas;
import java.awt.Color;
import java.awt.Insets;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import javax.inject.Inject;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.Border;
import javax.swing.border.EmptyBorder;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.HotkeyListener;

@Slf4j
@PluginDescriptor(
	name = "Black Screen Focus",
	description = "Shrink the game to a % of the window and leave the rest black, for less mouse travel",
	tags = {"resize", "shrink", "stretched", "focus", "black", "toa", "pvp", "screen"}
)
public class BlackScreenFocusPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private BlackScreenFocusConfig config;

	@Inject
	private KeyManager keyManager;

	/** The black panel RuneLite wraps around the game canvas. Touch on the EDT only. */
	private JPanel gamePanel;
	private Border originalBorder;
	private Color originalBackground;

	/** Hotkey flips this; plugin enabled + shrunk is the default. */
	private boolean shrunk = true;

	private final ComponentAdapter resizeListener = new ComponentAdapter()
	{
		@Override
		public void componentResized(ComponentEvent e)
		{
			applyLayout();
		}
	};

	private final HotkeyListener hotkeyListener = new HotkeyListener(() -> config.toggleHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			SwingUtilities.invokeLater(() ->
			{
				shrunk = !shrunk;
				applyLayout();
			});
		}
	};

	@Provides
	BlackScreenFocusConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BlackScreenFocusConfig.class);
	}

	@Override
	protected void startUp()
	{
		keyManager.registerKeyListener(hotkeyListener);
		shrunk = true;
		SwingUtilities.invokeLater(() ->
		{
			Canvas canvas = client.getCanvas();
			gamePanel = canvas == null ? null
				: (JPanel) SwingUtilities.getAncestorOfClass(JPanel.class, canvas);
			if (gamePanel == null)
			{
				log.warn("Black Screen Focus: could not find the game panel, doing nothing");
				return;
			}

			originalBorder = gamePanel.getBorder();
			originalBackground = gamePanel.getBackground();
			gamePanel.addComponentListener(resizeListener);
			applyLayout();
		});
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(hotkeyListener);
		SwingUtilities.invokeLater(() ->
		{
			if (gamePanel == null)
			{
				return;
			}
			gamePanel.removeComponentListener(resizeListener);
			gamePanel.setBorder(originalBorder);
			gamePanel.setBackground(originalBackground);
			gamePanel.revalidate();
			gamePanel.repaint();
			gamePanel = null;
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (BlackScreenFocusConfig.GROUP.equals(event.getGroup()))
		{
			SwingUtilities.invokeLater(this::applyLayout);
		}
	}

	/** EDT only. */
	private void applyLayout()
	{
		if (gamePanel == null)
		{
			return;
		}

		Insets insets = shrunk
			? ViewportMath.insets(
				gamePanel.getWidth(),
				gamePanel.getHeight(),
				config.widthPercent(),
				config.linkHeight() ? config.widthPercent() : config.heightPercent(),
				config.horizontal().fraction,
				config.vertical().fraction)
			: new Insets(0, 0, 0, 0);

		gamePanel.setBackground(config.background());

		// Skip no-op updates: avoids a relayout on every resize event while dragging.
		Insets current = gamePanel.getInsets();
		if (!current.equals(insets))
		{
			gamePanel.setBorder(new EmptyBorder(insets));
			gamePanel.revalidate();
			gamePanel.repaint();
		}
	}
}

package com.blackscreenfocus;

import java.awt.Insets;

/**
 * Pure geometry: given the full size of the game panel and a target size in percent,
 * work out the black padding (insets) that leaves the game area in the requested spot.
 */
final class ViewportMath
{
	static final int MIN_PERCENT = 20;
	static final int MAX_PERCENT = 100;

	private ViewportMath()
	{
	}

	/**
	 * @param panelWidth  full panel width in px
	 * @param panelHeight full panel height in px
	 * @param widthPct    game area width, percent of panel (clamped to 20-100)
	 * @param heightPct   game area height, percent of panel (clamped to 20-100)
	 * @param alignX      0 = left, 0.5 = centre, 1 = right
	 * @param alignY      0 = top, 0.5 = centre, 1 = bottom
	 */
	static Insets insets(int panelWidth, int panelHeight, int widthPct, int heightPct, double alignX, double alignY)
	{
		if (panelWidth <= 0 || panelHeight <= 0)
		{
			return new Insets(0, 0, 0, 0);
		}

		int gameW = scaled(panelWidth, widthPct);
		int gameH = scaled(panelHeight, heightPct);

		int spareX = panelWidth - gameW;
		int spareY = panelHeight - gameH;

		int left = (int) Math.round(spareX * alignX);
		int top = (int) Math.round(spareY * alignY);

		return new Insets(top, left, spareY - top, spareX - left);
	}

	private static int scaled(int full, int pct)
	{
		int clamped = Math.max(MIN_PERCENT, Math.min(MAX_PERCENT, pct));
		return Math.max(1, (int) Math.round(full * clamped / 100.0));
	}
}

package com.blackscreenfocus;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/** Launches a RuneLite dev client with this plugin preloaded. Run with: gradlew run */
public class BlackScreenFocusPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BlackScreenFocusPlugin.class);
		RuneLite.main(args);
	}
}

package com.blackscreenfocus;

import java.awt.Insets;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class ViewportMathTest
{
	@Test
	public void centredSixtyPercent()
	{
		// 2000x1000 panel, 60% -> 1200x600 game, 800x400 spare split evenly
		assertEquals(new Insets(200, 400, 200, 400), ViewportMath.insets(2000, 1000, 60, 60, 0.5, 0.5));
	}

	@Test
	public void insetsAlwaysAddUpToPanel()
	{
		for (int w = 1; w < 40; w += 7)
		{
			for (int pct = 20; pct <= 100; pct += 13)
			{
				Insets i = ViewportMath.insets(1921 + w, 1081 + w, pct, pct, 0.5, 0.5);
				int gameW = 1921 + w - i.left - i.right;
				assertEquals(Math.round((1921 + w) * pct / 100.0), gameW);
			}
		}
	}

	@Test
	public void alignedToCorners()
	{
		assertEquals(new Insets(0, 0, 400, 800), ViewportMath.insets(2000, 1000, 60, 60, 0, 0));
		assertEquals(new Insets(400, 800, 0, 0), ViewportMath.insets(2000, 1000, 60, 60, 1, 1));
	}

	@Test
	public void hundredPercentIsNoPadding()
	{
		assertEquals(new Insets(0, 0, 0, 0), ViewportMath.insets(1920, 1080, 100, 100, 0.5, 0.5));
	}

	@Test
	public void clampsAbsurdValues()
	{
		assertEquals(new Insets(0, 0, 0, 0), ViewportMath.insets(1920, 1080, 500, 500, 0.5, 0.5));
		// 1% is clamped up to the 20% floor so the game can never vanish
		assertEquals(new Insets(432, 768, 432, 768), ViewportMath.insets(1920, 1080, 1, 1, 0.5, 0.5));
	}

	@Test
	public void zeroSizedPanelIsSafe()
	{
		assertEquals(new Insets(0, 0, 0, 0), ViewportMath.insets(0, 0, 60, 60, 0.5, 0.5));
	}
}
